            account_id: string;
            /** Сумма, которую необходимо перечислить магазину */
            amount: IAmount;
            /** Комиссия за проданные товары и услуги, удерживаемая с магазина */
            platform_fee_amount?: IAmount;
            /** Описание транзакции (до 128 символов) */
